-- The rest of the farmer's Farmer Registry record on the Livestock Farmer tab:
-- personal, socio-economic and health details, contact and address, and the
-- photo in the record header. The Farmer reference copies these from the
-- Farmer Registry's signed DCI response (farmer_reference/profile.py); the
-- Fayda verification, the documents and the staff who created or approved the
-- record there are not copied. The sections are read-only: the farmer's
-- details change in the Farmer Registry and reach this registry with its
-- change notice. Every phone number is kept in the phones column; the tab
-- shows the primary one.
--
-- Idempotent: section upserts, tab-section inserts and a header update that
-- only adds the photo paths.

UPDATE "public"."g2p_register_definitions" SET "has_image" = TRUE
WHERE "register_id" = 'f9c6a359-9563-5a43-b0fe-6c7e452037a3' AND "has_image" IS DISTINCT FROM TRUE;

-- The photo in the record header (the header-section widget shows
-- record_image_document_id through record_image_url).
UPDATE "public"."g2p_register_sections"
SET "section_ui_schema" = jsonb_set("section_ui_schema", '{panels,0,panels,0,widgets,0,widget-data-path}',
      ("section_ui_schema" #> '{panels,0,panels,0,widgets,0,widget-data-path}') ||
      '{"image": "f9c6a359-9563-5a43-b0fe-6c7e452037a3.record_image_document_id", "imageUrl": "f9c6a359-9563-5a43-b0fe-6c7e452037a3.record_image_url"}'::jsonb)
WHERE "section_id" = 'livestock_farmer_record_header'
  AND "section_ui_schema" #>> '{panels,0,panels,0,widgets,0,widget}' = 'header-section'
  AND NOT ("section_ui_schema" #> '{panels,0,panels,0,widgets,0,widget-data-path}') ? 'image';

