y": true, "widget-required": false, "widget-data-path": "f9c6a359-9563-5a43-b0fe-6c7e452037a3.rid"}, {"widget": "display", "widget-id": "farmer_reference_odk_farmer_id", "widget-type": "display", "widget-label": "ODK Farmer ID", "widget-readonly": true, "widget-required": false, "widget-data-path": "f9c6a359-9563-5a43-b0fe-6c7e452037a3.odk_farmer_id"}, {"widget": "display", "widget-id": "farmer_reference_pula_id", "widget-type": "display", "widget-label": "Pula ID", "widget-readonly": true, "widget-required": false, "widget-data-path": "f9c6a359-9563-5a43-b0fe-6c7e452037a3.pula_id"}]}]}]}'::jsonb,
